assignments.value:
={{
(() => {
  const rows = $json.data.rows;

  const headers = ["Date", "Campaign Name", "Error Description"];

  const escape = (v) => v === null || v === undefined ? "" : String(v).replace(/\|/g, "\\|").replace(/\n/g, " ");

  const headerRow = "| " + headers.join(" | ") + " |";
  const separator = "| " + headers.map(() => "---").join(" | ") + " |";
  const dataRows = rows.map(row => "| " + row.map(v => escape(v)).join(" | ") + " |").join("\n");

  return [headerRow, separator, dataRows].join("\n");
})()
}}

